effect.shader:
float gmHash(vec2 p){ return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123); }
float gmNoise(vec2 p){
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(gmHash(i), gmHash(i + vec2(1.0, 0.0)), u.x),
             mix(gmHash(i + vec2(0.0, 1.0)), gmHash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float gmFbm(vec2 p){
  float total = 0.0, amp = 0.5;
  for (int i = 0; i < 5; i++){
    total += amp * gmNoise(p);
    p = p * 2.07 + 13.1;
    amp *= 0.5;
  }
  return total;
}
void main(){
  vec2 baseUv = acScreenNorm;
  float t = acTime * speed;
  float n1 = gmFbm(baseUv * scale + vec2(t * 1.3, -t * 0.7));
  float n2 = gmFbm(baseUv.yx * scale + vec2(-t, t * 1.4) + 17.0);
  vec2 offset = (vec2(n1, n2) - 0.5) * 2.0 * amount * mixAmt;
  vec2 warped = baseUv + offset;
  vec4 origin = texture2DCv(inputImg.texture, baseUv);
  vec4 sr = texture2DCv(inputImg.texture, warped + vec2(chroma * mixAmt, 0.0));
  vec4 sg = texture2DCv(inputImg.texture, warped);
  vec4 sb = texture2DCv(inputImg.texture, warped - vec2(chroma * mixAmt, 0.0));
  float a = max(origin.a, 1e-4);
  vec3 broken = vec3(sr.r / max(sr.a, 1e-4), sg.g / max(sg.a, 1e-4), sb.b / max(sb.a, 1e-4));
  vec4 outSrc = vec4(clamp(broken, 0.0, 1.0) * a, a);
  gl_FragColor = mix(origin, outSrc, mixAmt);
}
